WITH parsed AS (SELECT id, customer_id, coupon_codes, items, ship_to, ship_to.country AS ship_country, TRY_CAST(attributes['weight_kg'] AS DOUBLE) AS weight_kg FROM carts) SELECT CASE WHEN weight_kg >= 3.8 THEN 'LARGE' ELSE 'SMALL' END AS weight_kg_tier, ship_country, APPROX_PERCENTILE(weight_kg, ARRAY(0.25, 0.5, 0.75)) AS weight_kg_quartiles, ROUND(AVG(weight_kg), 2) AS avg_weight_kg, COUNT_IF(ship_country = 'UK') AS uk_events FROM parsed GROUP BY CASE WHEN weight_kg >= 3.8 THEN 'LARGE' ELSE 'SMALL' END, ship_country
